/* Local, explainable companion. No LLM request or device connection is performed. */
const ACTIVITY_LEVELS={unknown:'Поки не обрано',seated:'Переважно сиджу',light:'Сиджу, але регулярно ходжу',mixed:'Багато ходжу / працюю стоячи',physical:'Фізична робота / багато руху'};
let workoutFilter={group:'all',query:''},coachPeriod='day';
function sportOptions(){return state.settings;}
function coachSettings(){return state.settings.coach||{enabled:true,nutrition:true,sleep:true,move:true};}
function macroTargets(){return state.settings.macros||{p:null,f:null,c:null};}
function activityById(id){return ACTIVITY_CATALOG.find(a=>a.id===id);}
function metEstimate(met,weight,minutes,age=''){if(!Number.isFinite(met)||met<1||!Number.isFinite(weight)||weight<30||weight>400||!Number.isFinite(minutes)||minutes<=0||minutes>1440||(age!==''&&(Number(age)<19||Number(age)>59)))return null;const factor=3.5*weight/200*minutes;return{activeKcal:(met-1)*factor,grossKcal:met*factor};}
function normalizeWorkout(w,checkNumber,checkId,checkString){const n=(v,max)=>checkNumber(v,max,true);return{id:checkId(w.id),name:checkString(w.name,80),minutes:checkNumber(w.minutes,1440),activityId:activityById(w.activityId)?w.activityId:null,source:['met','watch-manual','manual'].includes(w.source)?w.source:'legacy',activeKcal:n(w.activeKcal,50000),grossKcal:n(w.grossKcal,50000),weight:n(w.weight,400),met:n(w.met,30),distance:n(w.distance,1000),startTime:typeof w.startTime==='string'&&/^([01]\d|2[0-3]):[0-5]\d$/.test(w.startTime)?w.startTime:'',notes:checkString(w.notes,200),countEnergy:w.countEnergy!==false};}
function movementTotals(d=selectedDate){const l=state.logs[d],ws=l?.workouts||[],known=ws.filter(w=>w.countEnergy!==false&&Number.isFinite(w.activeKcal)),watch=l?.dailyActivity;return{minutes:ws.reduce((s,w)=>s+w.minutes,0),sessions:ws.length,workoutKcal:known.reduce((s,w)=>s+w.activeKcal,0),unknown:ws.filter(w=>w.countEnergy!==false&&!Number.isFinite(w.activeKcal)).length,activeKcal:Number.isFinite(watch?.activeKcal)?watch.activeKcal:known.length?known.reduce((s,w)=>s+w.activeKcal,0):null,hasDayWatch:Number.isFinite(watch?.activeKcal),device:watch?.device||'',steps:l?.steps||0};}
function dumbbellArt(){return '<svg viewBox="0 0 70 70" class="dumbbell-art" aria-hidden="true"><g transform="rotate(-28 35 35)"><rect x="10" y="18" width="13" height="34" rx="5"/><rect x="47" y="18" width="13" height="34" rx="5"/><rect x="5" y="25" width="8" height="20" rx="3"/><rect x="58" y="25" width="8" height="20" rx="3"/><rect x="22" y="30" width="26" height="10" rx="4"/></g></svg>';}
function rhythmBanner(){return '<section class="rhythm-banner"><img src="assets/movement-editorial.png" alt="Фітнес-ілюстрація: доросла жінка у спортивному одязі" loading="lazy"><div class="rhythm-shade"></div><div class="rhythm-copy"><span>ТВОЇ РІШЕННЯ. ТВІЙ РИТМ.</span><h2>Тримай курс.<br>Крок за кроком.</h2><p>Цілі, рух і звички —<br>в одному місці.</p><button data-view="move">Мій рух '+icon('arrow')+'</button></div><div class="rhythm-badge">'+dumbbellArt()+'<span>Сила<br>малих дій</span></div><div class="rhythm-ticks" aria-hidden="true">✓ ✓ ✦</div></section>';}
function sportHomeCard(){const t=movementTotals();return '<button class="sport-home-card" data-view="move"><span class="sport-home-icon">'+dumbbellArt()+'</span><span><small>МІЙ РУХ</small><strong>'+ (t.minutes?num(t.minutes)+' хв у твоїй історії':'Тренування, дім чи прогулянка')+'</strong><em>'+num(t.steps)+' кроків · '+(t.activeKcal===null?'витрати ще не внесено':'≈ '+num(t.activeKcal)+' активних ккал')+'</em></span><b>↗</b></button>';}
function activityChooser(){modalData={mode:'activity-picker'};openModal('РУХ / '+ACTIVITY_CATALOG.length+' ВАРІАНТІВ','<h2 class="modal-title">Як рухався<br>твій день?</h2><p class="modal-sub">Зал — лише один із варіантів. Обери активність і темп, найближчі до твоїх.</p><label class="recipe-search">'+icon('search')+'<input id="activitySearch" type="search" value="'+esc(workoutFilter.query)+'" placeholder="Ходьба, силове, пілатес, прибирання…" aria-label="Знайти активність"></label><div class="activity-categories">'+[['all','Усе'],...Object.entries(ACTIVITY_GROUPS).map(([id,g])=>[id,g.name])].map(([id,n])=>'<button class="pill '+(workoutFilter.group===id?'active':'')+'" data-action="activity-group" data-id="'+id+'">'+n+'</button>').join('')+'</div><div id="activityResults" class="activity-results"></div><button class="btn ghost full" data-action="workout-custom">＋ Своя активність</button>');$('activitySearch').oninput=e=>{workoutFilter.query=e.target.value;renderActivities();};renderActivities();}
function renderActivities(){let q=workoutFilter.query.toLocaleLowerCase('uk').trim();const aliases={'бег':'біг','ходьба':'ходьб','зал':'силов','йога':'йог','танцы':'танц','силовая':'силов','hiit':'інтерваль','пилатес':'пілатес','гантелі':'силов'};q=aliases[q]||q;const list=ACTIVITY_CATALOG.filter(a=>(workoutFilter.group==='all'||a.category===workoutFilter.group)&&(!q||(a.name+' '+ACTIVITY_GROUPS[a.category].name).toLocaleLowerCase('uk').includes(q)));$('activityResults').innerHTML='<p class="filter-note">Знайдено: '+list.length+'</p>'+list.map(a=>'<button class="activity-pick" data-action="workout-choose" data-id="'+a.id+'"><span>'+ACTIVITY_GROUPS[a.category].icon+'</span><span><strong>'+esc(a.name)+'</strong><small>'+ACTIVITY_GROUPS[a.category].name+'</small></span><i>＋</i></button>').join('')+(list.length?'':'<p class="empty">Спробуй іншу назву або додай свою активність.</p>');}
function workoutEditor(activityId=null,existing=null){const a=activityById(activityId),w=existing||{},weight=w.weight||Number(state.profile.weight)||'',source=w.source==='watch-manual'?'watch':w.source==='manual'?'manual':'met';modalData={mode:'workout',workoutId:w.id||null,activityId:a?.id||null};openModal('МІЙ РУХ / '+(existing?'РЕДАГУВАННЯ':'НОВА АКТИВНІСТЬ'),'<h2 class="modal-title">'+esc(a?.name||w.name||'Свій рух.')+'</h2><form id="workoutForm">'+(!a?'<label class="form-label">Назва активності<input name="name" maxlength="80" value="'+esc(w.name||'')+'" required placeholder="Що ти робив / робила?"></label>':'<input type="hidden" name="name" value="'+esc(a.name)+'">')+'<div class="form-pair"><label class="form-label">Тривалість, хв<input id="workoutMinutes" name="minutes" type="number" min="1" max="1440" step="1" value="'+(w.minutes||30)+'" required></label><label class="form-label">Початок · за бажанням<input name="startTime" type="time" value="'+esc(w.startTime||'')+'"></label></div><label class="form-label">Як врахувати витрати?<select id="workoutSource" name="energySource"><option value="met" '+(source==='met'?'selected':'')+'>Оцінити за активністю та вагою</option><option value="watch" '+(source==='watch'?'selected':'')+'>Внести активні ккал із годинника</option><option value="manual" '+(source==='manual'?'selected':'')+'>Записати тільки рух, без калорій</option></select></label><div id="workoutWeightWrap"><label class="form-label">Вага під час активності, кг<input id="workoutWeight" name="weight" type="number" min="30" max="400" step=".1" value="'+weight+'" placeholder="Для приблизної оцінки"><small>Не обов’язково зберігати вагу в профілі.</small></label></div><div id="workoutWatchWrap"><label class="form-label">Активні ккал саме цієї сесії<input id="workoutWatchKcal" name="watchKcal" type="number" min="0" max="50000" value="'+(w.source==='watch-manual'&&Number.isFinite(w.activeKcal)?w.activeKcal:'')+'" placeholder="З екрана тренування"><small>Введи активні, а не загальні калорії. Денні витрати внось окремо.</small></label></div><div id="workoutEstimate" class="workout-estimate" aria-live="polite"></div><div class="form-pair"><label class="form-label">Дистанція, км · необов’язково<input name="distance" type="number" min="0" max="1000" step=".01" value="'+(w.distance??'')+'"></label><label class="form-label">Нотатка<input name="notes" maxlength="200" value="'+esc(w.notes||'')+'" placeholder="Відчуття, підходи, вага…"></label></div><label class="recipe-checkbox"><input name="countEnergy" type="checkbox" '+(w.countEnergy!==false?'checked':'')+'>Врахувати витрати цієї сесії в підсумку</label><p class="filter-note">Якщо це частина вже внесеної сесії, вимкни врахування витрат. Кроки самі по собі не додають калорій.</p><p class="form-error" id="workoutError" role="alert"></p><button class="btn blue full" type="submit">'+(existing?'Зберегти зміни':'Додати до мого руху')+' ↗</button></form>');['workoutMinutes','workoutWeight','workoutWatchKcal'].forEach(id=>$(id).oninput=updateWorkoutEstimate);$('workoutSource').onchange=updateWorkoutEstimate;updateWorkoutEstimate();}
function updateWorkoutEstimate(){const source=$('workoutSource').value,a=activityById(modalData.activityId),weight=Number($('workoutWeight').value),minutes=Number($('workoutMinutes').value),est=a?metEstimate(a.met,weight,minutes,state.profile.age||''):null;$('workoutWeightWrap').hidden=source!=='met';$('workoutWatchWrap').hidden=source!=='watch';$('workoutWeight').required=false;$('workoutWatchKcal').required=source==='watch';$('workoutEstimate').innerHTML=source==='watch'?'<strong>Дані твого пристрою</strong><p>Внесення вручну. Автосинхронізація не підключена; годинник також оцінює витрати.</p>':source==='manual'?'<strong>Рух рахується й без цифри.</strong><p>Збережемо активність і тривалість.</p>':est?'<div><strong>≈ '+num(Math.round(est.activeKcal))+'</strong><span>активних ккал понад спокій</span></div><p>Загалом за цей час ≈ '+num(Math.round(est.grossKcal))+' ккал, включно зі спокоєм. Це середня оцінка для вибраного темпу, а не вимірювання.</p><details><summary>Звідки цифра?</summary><p>MET '+a.met+' · '+num(weight,1)+' кг · '+num(minutes)+' хв. Активні ккал = (MET − 1) × 3,5 × кг ÷ 200 × хв. <a href="'+a.url+'" target="_blank" rel="noopener">Compendium 2024 ↗</a></p></details>':'<strong>Поки без оцінки калорій</strong><p>'+(!a?'Для власної активності немає вибраного MET. Можна внести активні ккал із годинника або зберегти лише час.':state.profile.age&&(Number(state.profile.age)<19||Number(state.profile.age)>59)?'Цей довідник розрахований на вік 19–59 років. Збережемо рух без оцінки або внеси дані пристрою.':'Додай вагу 30–400 кг для розрахунку або залиш запис без калорій.')+'</p>';}
function saveWorkoutForm(v){const a=activityById(modalData.activityId),minutes=Number(v.minutes),weight=v.weight?Number(v.weight):null,src=v.energySource||'manual',est=a&&weight?metEstimate(a.met,weight,minutes,state.profile.age||''):null,existing=log().workouts.find(w=>w.id===modalData.workoutId);if(!Number.isFinite(minutes)||minutes<1||minutes>1440||!v.name?.trim())return;if(log().workouts.length>=100&&!existing){toast('У цьому дні вже 100 активностей');return;}if(v.startTime){const toMinute=t=>Number(t.slice(0,2))*60+Number(t.slice(3)),start=toMinute(v.startTime),overlap=log().workouts.some(w=>w.id!==modalData.workoutId&&w.startTime&&start<toMinute(w.startTime)+w.minutes&&start+minutes>toMinute(w.startTime));if(overlap&&!confirm('Час перетинається з іншою активністю. Якщо це той самий рух, повернись і вимкни врахування витрат. Зберегти окремий запис?'))return;}const w={id:existing?.id||uid(),name:v.name.trim(),activityId:a?.id||null,minutes,source:src==='watch'?'watch-manual':src==='met'&&est?'met':'manual',weight:src==='met'?weight:null,met:src==='met'&&est?a.met:null,activeKcal:src==='watch'?Number(v.watchKcal):src==='met'&&est?round(est.activeKcal):null,grossKcal:src==='met'&&est?round(est.grossKcal):null,distance:v.distance?Number(v.distance):null,startTime:v.startTime||'',notes:v.notes?.trim()||'',countEnergy:v.countEnergy==='on'};if(src==='watch'&&(!v.watchKcal||!Number.isFinite(w.activeKcal)||w.activeKcal<0||w.activeKcal>50000)){$('workoutError').textContent='Вкажи активні ккал із пристрою, від 0 до 50 000.';return;}const i=log().workouts.findIndex(x=>x.id===w.id);if(i>=0)log().workouts[i]=w;else log().workouts.push(w);log().habits.move=true;persist();closeModal();navigate('move');toast('Твій рух збережено. Підсумок дня оновлено.');}
function workoutRows(){return log().workouts.map(w=>'<article class="workout-row"><button class="workout-main" data-action="workout-edit" data-id="'+w.id+'"><span class="workout-symbol">'+(ACTIVITY_GROUPS[activityById(w.activityId)?.category]?.icon||'↗')+'</span><span><strong>'+esc(w.name)+'</strong><small>'+num(w.minutes)+' хв'+(w.distance?' · '+num(w.distance,2)+' км':'')+(w.startTime?' · '+esc(w.startTime):'')+' · '+(w.source==='met'?'оцінка за MET':w.source==='watch-manual'?'із годинника вручну':'внесено вручну')+'</small>'+(w.notes?'<small>'+esc(w.notes)+'</small>':'')+'</span><b>'+(Number.isFinite(w.activeKcal)?'≈ '+num(w.activeKcal)+'<small>активних ккал'+(w.countEnergy===false?' · виключено':'')+'</small>':'—<small>без оцінки</small>')+'</b></button><button class="workout-delete" data-action="delete-workout" data-id="'+w.id+'" aria-label="Видалити '+esc(w.name)+'">×</button></article>').join('')||'<div class="empty">Ще немає записів за цей день.<br>Дім, прогулянка, танці — усе має місце.</div>';}
function movementWeek(){const days=Array.from({length:7},(_,i)=>offset(selectedDate,i-6)),values=days.map(d=>movementTotals(d)),max=Math.max(30,...values.map(v=>v.minutes));return '<div class="movement-week">'+days.map((d,i)=>'<button data-action="movement-day" data-date="'+d+'" aria-label="'+fdate(d)+' — '+values[i].minutes+' хв внесено"><b>'+ (values[i].minutes?num(values[i].minutes):'—')+'</b><span><i style="height:'+Math.max(3,values[i].minutes/max*85)+'px"></i></span><small>'+new Intl.DateTimeFormat('uk-UA',{weekday:'short',timeZone:'UTC'}).format(dt(d))+'</small></button>').join('')+'</div><p class="filter-note">Хвилини внесених сесій за 7 днів. Порожня дата не означає відсутність руху.</p>';}
function sportView(){const t=movementTotals(),level=ACTIVITY_LEVELS[state.profile.activityLevel]||ACTIVITY_LEVELS.unknown;return pageTop('Твій рух. Увесь.','СПОРТ / '+fdate(selectedDate),dateControl())+'<section class="sport-hero"><div class="sport-hero-art">'+dumbbellArt()+'</div><span class="overline">РУХ У ТВОЄМУ ТЕМПІ</span><h2>'+num(t.minutes)+'<small> хв</small></h2><p>Записаних сесій сьогодні: '+num(t.sessions)+'</p><button class="btn" data-action="workout">＋ Додати активність</button></section><div class="sport-summary"><button data-action="steps"><small>Кроки за день</small><strong>'+num(t.steps)+'</strong><span>Внести / змінити ↗</span></button><button data-action="watch-day"><small>'+(t.hasDayWatch?'Активність за весь день':'Витрати внесених сесій')+'</small><strong>'+(t.activeKcal===null?'—':'≈ '+num(t.activeKcal))+'</strong><span>активних ккал '+(t.hasDayWatch?'· із годинника вручну':'· за наявними оцінками')+'</span></button></div>'+(t.unknown?'<p class="data-note">Без оцінки витрат: '+t.unknown+' сесій. Підсумок може бути неповним.</p>':'')+(t.hasDayWatch?'<p class="data-note">За основу взято денні активні ккал із '+esc(t.device)+'. Витрати сесій показуємо окремо й не додаємо вдруге.</p>':'')+'<div class="sport-shortcuts"><button data-action="workout-choose" data-id="met-17190">↗ Ходьба</button><button data-action="workout-choose" data-id="met-02054">'+icon('move')+' Силове</button><button data-action="workout-choose" data-id="met-02064">⌂ Вдома</button></div><section class="panel"><div class="panel-head"><h2>Мої активності</h2><button class="text-btn" data-action="workout">Усі '+ACTIVITY_CATALOG.length+' ↗</button></div>'+workoutRows()+'</section><section class="panel bottom-space"><div class="panel-head"><h2>Ритм за тиждень</h2><span class="chip">хвилини</span></div>'+movementWeek()+'</section><button class="daily-context" data-action="body-settings"><span>'+dumbbellArt()+'</span><span><strong>Мій звичайний день</strong><small>'+esc(level)+' · параметри й орієнтири</small></span><b>↗</b></button><button class="coach-link" data-view="coach"><span>✦ Рух + сон + харчування</span><strong>Що помітив мій помічник? ↗</strong></button><section class="panel bottom-space"><h2>Мої пристрої</h2><p class="section-sub">Apple Health / Health Connect</p><button class="btn ghost full" data-action="watch-day">⌚ Внести денні дані годинника</button><button class="text-btn full" data-action="integration">Як працюватиме автоматичне підключення ↗</button><p class="filter-note">Кроки не переводимо в калорії та не додаємо поверх тренувань. Витрати руху не збільшують автоматично орієнтир їжі.</p></section>';}
function watchDayModal(){const w=log().dailyActivity||{};openModal('ПРИСТРОЇ / ДЕННИЙ ПІДСУМОК ВРУЧНУ','<h2 class="modal-title">З годинника —<br>у твою історію.</h2><p class="modal-sub">Перенеси показники за '+fdate(selectedDate)+'. Це ручний запис, автосинхронізацію ще не підключено.</p><form id="watchDayForm"><label class="form-label">Звідки дані?<select name="device">'+['Apple Watch / Apple Health','Android / Health Connect','Garmin','Fitbit','Samsung Health','Інший пристрій'].map(n=>'<option '+(w.device===n?'selected':'')+'>'+n+'</option>').join('')+'</select></label><label class="form-label">Активні ккал за весь обраний день<input name="activeKcal" type="number" min="0" max="50000" value="'+(w.activeKcal??'')+'" placeholder="Залиш порожнім, щоб прибрати"><small>Активні / Move, без калорій спокою. Це вже містить тренування за день.</small></label><label class="form-label">Кроки за весь день<input name="steps" type="number" min="0" max="200000" value="'+log().steps+'" required></label><p class="note">Денний показник замінить підсумок витрат сесій, а не додасться до нього. Повторне збереження оновлює той самий день.</p><button class="btn blue full">Зберегти денні показники</button></form>');}
function bodySettingsModal(){const p=state.profile,m=macroTargets(),s=state.settings,c=coachSettings();openModal('МІЙ КОНТЕКСТ / ЗА БАЖАННЯМ','<h2 class="modal-title">Помічник знає<br>твій ритм.</h2><p class="modal-sub">Обери звичайну активність і власні орієнтири. Власні орієнтири можна внести тут; для стартового розрахунку є окрема кнопка в помічнику.</p><form id="bodySettingsForm"><label class="form-label">Який твій звичайний день?<select name="activityLevel">'+Object.entries(ACTIVITY_LEVELS).map(([k,n])=>'<option value="'+k+'" '+(p.activityLevel===k?'selected':'')+'>'+n+'</option>').join('')+'</select></label><div class="form-triple"><label class="form-label">Вік<input name="age" type="number" min="18" max="100" value="'+esc(p.age||'')+'"></label><label class="form-label">Зріст, см<input name="height" type="number" min="100" max="250" value="'+esc(p.height||'')+'"></label><label class="form-label">Вага, кг<input name="weight" type="number" min="30" max="400" step=".1" value="'+esc(p.weight||'')+'"></label></div><h3>Мої орієнтири БЖВ</h3><p class="filter-note">Необов’язкові власні значення, наприклад узгоджені з фахівцем. Помічник порівнює записи з ними й не оцінює «правильність» їжі.</p><div class="form-triple">'+[['p','Білки'],['f','Жири'],['c','Вуглеводи']].map(([k,n])=>'<label class="form-label">'+n+', г<input name="'+k+'" type="number" min="1" max="1000" value="'+(m[k]||'')+'" placeholder="Без орієнтира"></label>').join('')+'</div><div class="form-pair"><label class="form-label">Мій сон, годин<input name="sleep" type="number" min="1" max="24" step=".1" value="'+(s.sleep||'')+'" placeholder="Необов’язково"></label><label class="form-label">Мій рух, хв / тиждень<input name="weeklyMinutes" type="number" min="1" max="10080" value="'+(s.weeklyMinutes||'')+'" placeholder="Необов’язково"></label></div><h3>Підказки в застосунку</h3>'+[['enabled','Увімкнути помічника'],['nutrition','Харчування та орієнтири'],['sleep','Сон і відновлення'],['move','Рух і звички']].map(([k,n])=>'<label class="recipe-checkbox"><input name="coach_'+k+'" type="checkbox" '+(c[k]!==false?'checked':'')+'>'+n+'</label>').join('')+'<p class="filter-note">Підказки з’являються в застосунку, коли ти вносиш дані. Push-сповіщення у фоні не підключені.</p><button class="btn blue full">Зберегти мій контекст</button></form>');}
function macroCoverage(d=selectedDate){const ms=state.logs[d]?.meals||[];return Object.fromEntries(['p','f','c'].map(k=>[k,{known:ms.filter(m=>Number.isFinite(m[k])).length,total:ms.length,complete:ms.length>0&&ms.every(m=>Number.isFinite(m[k]))}]));}
function dayInsights(d=selectedDate){const l=state.logs[d]||{},t=totals(d),mv=movementTotals(d),targets=macroTargets(),coverage=macroCoverage(d),c=coachSettings(),ins=[];const add=(id,tone,title,body,action,label)=>ins.push({id,tone,title,body,action,label});if(!c.enabled)return ins;
 if(c.sleep){const h=sleepDuration(l.sleep);if(h&&(h<7||l.sleep?.quality==='tired'))add('sleep','lavender','Сьогодні більше опори на відновлення','У записі '+hoursText(h)+(l.sleep?.quality==='tired'?' і відчуття втоми.':'.')+' Недосип може посилювати голод, але не визначає, як мине твій день. Заплануй зручну їжу й обери рух за самопочуттям.','sleep','Мій сон');else if(!l.sleep)add('no-sleep','neutral','Для повнішої картини бракує сну','Додай час і своє відчуття після ночі — помічник врахує їх у розборі.','sleep','Додати сон');}
 if(c.nutrition){if(!l.meals?.length)add('no-food','neutral','Почнемо з одного запису','Ще немає записів їжі за цей день. Відсутність запису не означає, що ти не їв / не їла.','food','Відкрити щоденник');else{if(t.missing||Object.values(coverage).some(x=>!x.complete))add('partial','neutral','Підсумок харчування неповний','Не всі записи містять калорії або БЖВ. Показуємо внесені дані; там, де БЖВ невідомі, не робимо висновку про нестачу чи надлишок.','food','Уточнити записи');for(const[k,n]of [['p','білків'],['f','жирів'],['c','вуглеводів']]){if(!targets[k]||!coverage[k].complete)continue;const gap=targets[k]-t[k];if(gap<0)add('macro-'+k,'peach','Внесено більше '+n+' за твій орієнтир','У щоденнику '+num(t[k],1)+' г, твій орієнтир — '+num(targets[k])+' г. Це порівняння з обраною цифрою, а не оцінка здоров’я чи прогноз голоду. Не потрібно компенсувати це пропуском їжі.','food','Переглянути записи');else if(gap>0&&l.nutritionComplete)add('macro-'+k,'lime','Підсумок '+n+' нижчий за твій орієнтир','Позначено, що їжу за день внесено повністю: '+num(t[k],1)+' із '+num(targets[k])+' г. За одним днем не визначаємо дефіцит поживних речовин і не передбачаємо переїдання. За бажанням переглянь склад звичних страв.',k==='p'?'protein-ideas':'recipes',k==='p'?'Ідеї страв із білком':'Ідеї наступних страв');}}
 if(!Object.values(targets).some(Boolean))add('targets','neutral','Помічник підлаштовується під тебе','Додай власні орієнтири БЖВ, якщо користуєшся ними. Без них не будемо називати кількість «завеликою» чи «замалою».','body-settings','Мої орієнтири');}
 if(l.checkIn?.hunger==='high')add('hunger','peach','Твій голод заслуговує на увагу','Ти відзначив / відзначила сильний голод. Можна зробити паузу на звичайний прийом їжі або перекус і перевірити самопочуття. Це не оцінка твоєї дисципліни.','recipes','Обрати їжу');
 if(c.move){if(mv.sessions)add('movement','lime','Твій рух уже в історії','Рух: '+num(mv.minutes)+' хв. Сесій: '+num(mv.sessions)+'. '+(l.sleep?.quality==='tired'?'Ти відзначив / відзначила втому після сну — наступну активність можна обрати легшою.':'Обирай наступний крок за власним самопочуттям; відновлення теж частина ритму.'),'move','Мій рух');else if(state.profile.activityLevel==='seated'||state.profile.activityLevel==='light')add('break','lime','Маленький рух між справами','Твій звичайний день переважно сидячий. Якщо зараз зручно й самопочуття дозволяє, можна встати, змінити позу або трохи пройтися.','move','Записати рух');}
 return ins;}
function coachTeaser(){const all=dayInsights(),top=all.find(x=>!['no-sleep','targets','no-food'].includes(x.id))||all[0];return '<button class="coach-teaser" data-view="coach"><span class="coach-orb">✦</span><span><small>ПОМІЧНИК ДНЯ · '+(coachSettings().enabled?'АВТООНОВЛЕННЯ':'ПІДКАЗКИ ВИМКНЕНО')+'</small><strong>'+esc(top?.title||'Твій день у цілісній картині')+'</strong><em>Сон, харчування, рух і твій прогрес</em></span><b>↗</b></button>';}
function macroProgress(){const t=totals(),target=macroTargets(),coverage=macroCoverage();return '<section class="panel macro-progress"><button class="btn ghost full" data-action="plan">✦ Розрахувати / оновити стартовий план</button><div class="panel-head"><h2>Мої БЖВ</h2><button class="text-btn" data-action="body-settings">Орієнтири ↗</button></div>'+[['p','Білки'],['f','Жири'],['c','Вуглеводи']].map(([k,n])=>'<div class="macro-line"><div><strong>'+n+'</strong><span>'+num(t[k],1)+(target[k]?' / '+num(target[k]):'')+' г'+(!coverage[k].complete?' · неповні дані':'')+'</span></div><div class="macro-track '+k+'"><i style="width:'+(target[k]?Math.min(100,t[k]/target[k]*100):0)+'%"></i></div><small>'+(target[k]?(t[k]>target[k]?'Вище власного орієнтира на '+num(t[k]-target[k],1)+' г':'До власного орієнтира '+num(target[k]-t[k],1)+' г'):'Без заданого орієнтира')+'</small></div>').join('')+'<button class="nutrition-complete '+(log().nutritionComplete?'done':'')+'" data-action="nutrition-complete" aria-pressed="'+!!log().nutritionComplete+'"><span>'+(log().nutritionComplete?'✓':'○')+'</span><span><b>Їжу за цей день внесено повністю</b><small>Це про повноту записів. Можна змінити будь-коли.</small></span></button></section>';}
function weekSummary(){const days=Array.from({length:7},(_,i)=>offset(selectedDate,i-6)),workouts=days.map(d=>movementTotals(d)),nights=days.map(d=>sleepDuration(state.logs[d]?.sleep)).filter(Boolean),minutes=workouts.reduce((s,x)=>s+x.minutes,0),marks=days.filter(d=>goal().checks[d]).length,activeDays=workouts.filter(x=>x.sessions>0).length,foodDays=days.filter(d=>state.logs[d]?.meals?.length).length,completeDays=days.filter(d=>state.logs[d]?.nutritionComplete).length;return{days,minutes,nights,sleepAvg:nights.length?nights.reduce((a,b)=>a+b,0)/nights.length:null,marks,activeDays,foodDays,completeDays};}
function coachWeek(){const w=weekSummary(),target=state.settings.weeklyMinutes;return '<section class="week-recap"><span class="overline">7 ДНІВ ДО '+fdate(selectedDate).toUpperCase()+'</span><h2>Бачити свій шлях.<br>Без оцінок себе.</h2><div class="recap-stats"><div><b>'+w.marks+'</b><span>днів відзначено<br>в активній цілі</span></div><div><b>'+w.activeDays+'</b><span>днів із внесеними<br>активностями</span></div><div><b>'+num(w.minutes)+'</b><span>хвилин руху<br>'+(target?'твій орієнтир '+num(target):'у записаних сесіях')+'</span></div><div><b>'+(w.sleepAvg?num(w.sleepAvg,1):'—')+'</b><span>годин сну в середньому<br>за '+w.nights.length+' записами</span></div></div></section><section class="panel bottom-space"><h2>Що бачимо за записами</h2><p class="section-sub">Їжа внесена у '+w.foodDays+' із 7 днів; повноту позначено у '+w.completeDays+'. '+(w.nights.length<3?'Записів сну поки мало для висновків про тиждень.':'Середнє враховує лише внесені ночі. Це опис записів, а не оцінка здоров’я.')+'</p>'+(target?'<p>Внесено '+num(w.minutes)+' із власних '+num(target)+' хв за цей проміжок. Це рухоме вікно 7 днів, не календарний тиждень.</p>':'<button class="text-btn" data-action="body-settings">Додати свій орієнтир руху ↗</button>')+movementWeek()+'</section><button class="coach-link" data-view="journey"><span>ТВІЙ КАЛЕНДАР ЛИШАЄТЬСЯ З ТОБОЮ</span><strong>Побачити маленькі перемоги ↗</strong></button>';}
function coachView(){const list=dayInsights(),l=log();return pageTop('Помічник твого ритму.','СОН + ЇЖА + РУХ',dateControl())+'<div class="coach-toolbar"><div class="segmented"><button class="'+(coachPeriod==='day'?'active':'')+'" data-action="coach-period" data-id="day">День</button><button class="'+(coachPeriod==='week'?'active':'')+'" data-action="coach-period" data-id="week">7 днів</button></div><button class="icon-button" data-action="body-settings" aria-label="Налаштування помічника">⚙</button></div><div class="coach-intro"><span>✦</span><div><b>Твої дані → зрозумілий наступний крок</b><p>Автоаналіз за прозорими правилами. Живий AI-чат ще не підключено. Підказки оновлюються після внесення записів.</p></div></div>'+(coachPeriod==='week'?coachWeek():'<div class="coach-insights">'+(list.length?list.map(x=>'<article class="coach-insight '+x.tone+'"><span class="insight-symbol">'+({sleep:'☾',hunger:'♡',movement:'↗',break:'↗'}[x.id]||'✦')+'</span><h2>'+esc(x.title)+'</h2><p>'+esc(x.body)+'</p><button class="text-btn" '+(['body-settings','protein-ideas'].includes(x.action)?'data-action':'data-view')+'="'+x.action+'">'+x.label+' ↗</button></article>').join(''):'<section class="panel"><h2>Помічник зараз на паузі.</h2><p class="section-sub">Усі твої записи й календар доступні.</p><button class="text-btn" data-action="body-settings">Налаштувати підказки ↗</button></section>')+'</div>'+macroProgress()+'<section class="panel bottom-space"><div class="panel-head"><h2>Як ти зараз?</h2><button class="text-btn" data-action="check-in">'+(l.checkIn?'Змінити':'Відзначити')+' ↗</button></div><p class="section-sub">'+(l.checkIn?'Голод: '+({low:'невеликий',medium:'помірний',high:'сильний'}[l.checkIn.hunger]||'не вказано')+'. Енергія: '+({low:'низька',okay:'звичайна',high:'висока'}[l.checkIn.energy]||'не вказано')+'.':'Твоє відчуття важливіше за здогадку алгоритму. Голод і енергію можна відзначити для власного контексту.')+'</p></section>')+'<details class="coach-method"><summary>На чому ґрунтуються підказки?</summary><p>Порівнюємо тільки внесені значення з твоїми орієнтирами. Невідомі калорії та БЖВ не прирівнюємо до нуля. Не передбачаємо переїдання, гормональні зміни або результат схуднення.</p><p>Короткий сон: нижче 7 годин або твоє відчуття втоми. <a href="https://www.niddk.nih.gov/health-information/weight-management/adult-overweight-obesity/factors-affecting-weight-health" target="_blank" rel="noopener">NIDDK: сон може впливати на апетит ↗</a>. Враховуємо записаний час між засинанням і пробудженням, без нічних пробуджень.</p><p>Оцінки руху: <a href="https://pacompendium.com/adult-compendium/" target="_blank" rel="noopener">Compendium 2024, вік 19–59 ↗</a>. Середні MET не вимірюють твій особистий метаболізм. Коли вік не вказано, використовуємо дорослу модель 19–59; поза цим віком пропонуємо запис без MET.</p><p>Це органайзер і помічник для самоспостереження. Він не ставить діагнозів і не призначає харчування або тренування.</p></details>';}
function checkInModal(){const c=log().checkIn||{};openModal('МІЙ СТАН / БЕЗ ОЦІНОК','<h2 class="modal-title">Як ти зараз?</h2><form id="checkInForm"><label class="form-label">Мій голод<select name="hunger">'+[['low','Невеликий'],['medium','Помірний'],['high','Сильний']].map(([k,n])=>'<option value="'+k+'" '+(c.hunger===k?'selected':'')+'>'+n+'</option>').join('')+'</select></label><label class="form-label">Моя енергія<select name="energy">'+[['low','Низька'],['okay','Звичайна'],['high','Висока']].map(([k,n])=>'<option value="'+k+'" '+(c.energy===k?'selected':'')+'>'+n+'</option>').join('')+'</select></label><p class="note">Зберігаємо останню позначку за обраний день. Це твоє відчуття, а не діагноз.</p><button class="btn blue full">Відзначити стан</button></form>');}
function coachNotifications(){const list=dayInsights();$('coachNotice')?.setAttribute('aria-label','Помічник дня, підказок: '+list.length);if($('coachCount'))$('coachCount').textContent=list.length?String(list.length):'';}
